import '../../../services/food/food_service.dart'; import '../../messenger/presentation/messenger_screen.dart';
class AurenFoodScreen extends StatefulWidget{const AurenFoodScreen({super.key});@override State<AurenFoodScreen> createState()=>_AurenFoodScreenState();}
class _AurenFoodScreenState extends State<AurenFoodScreen>{String city='',country='',category=''; bool organic=false,vegetarian=false,vegan=false,athlete=false,highProtein=false,glutenFree=false,lactoseFree=false,lowSugar=false; bool halal=false,organic=false,vegan=false,vegetarian=false,athlete=false;
void _filter(){final a=TextEditingController(text:city),b=TextEditingController(text:country),c=TextEditingController(text:category);showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('فلترة الطعام والمنزل'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,decoration:const InputDecoration(labelText:'المدينة')),TextField(controller:b,decoration:const InputDecoration(labelText:'الدولة')),TextField(controller:c,decoration:const InputDecoration(labelText:'التصنيف (مطعم، بقالة، منزل...)')),SwitchListTile(title:const Text('عضوي'),value:organic,onChanged:(v)=>setState(()=>organic=v)),SwitchListTile(title:const Text('نباتي'),value:vegetarian,onChanged:(v)=>setState(()=>vegetarian=v)),SwitchListTile(title:const Text('Vegan'),value:vegan,onChanged:(v)=>setState(()=>vegan=v)),SwitchListTile(title:const Text('مناسب للرياضيين'),value:athlete,onChanged:(v)=>setState(()=>athlete=v)),SwitchListTile(title:const Text('عالي البروتين'),value:highProtein,onChanged:(v)=>setState(()=>highProtein=v)),SwitchListTile(title:const Text('خالٍ من الغلوتين'),value:glutenFree,onChanged:(v)=>setState(()=>glutenFree=v)),SwitchListTile(title:const Text('خالٍ من اللاكتوز'),value:lactoseFree,onChanged:(v)=>setState(()=>lactoseFree=v)),SwitchListTile(title:const Text('قليل السكر'),value:lowSugar,onChanged:(v)=>setState(()=>lowSugar=v)),SwitchListTile(title:const Text('حلال'),value:halal,onChanged:(v)=>setState(()=>halal=v)),SwitchListTile(title:const Text('عضوي Organic'),value:organic,onChanged:(v)=>setState(()=>organic=v)),SwitchListTile(title:const Text('نباتي Vegetarian'),value:vegetarian,onChanged:(v)=>setState(()=>vegetarian=v)),SwitchListTile(title:const Text('Vegan'),value:vegan,onChanged:(v)=>setState(()=>vegan=v)),SwitchListTile(title:const Text('مناسب للرياضيين'),value:athlete,onChanged:(v)=>setState(()=>athlete=v))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:(){setState((){city=a.text