@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(appBar:AppBar(title:const Text('AUREN Food + Home'),actions:[IconButton(icon:const Icon(Icons.auto_awesome),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const MessengerScreen(initialPrompt:'ساعدني أختار الطعام أو مستلزمات المنزل حسب المدينة والميزانية والتفضيلات، وراعِ خيار الحلال عند طلبه.')))),IconButton(onPressed:_filter,icon:const Icon(Icons.tune))]),body:uid==null?const Center(child:Text('سجّل الدخول لاستخدام الخدمة.')):StreamBuilder<List<AurenFoodItem>>(stream:AurenFoodService.instance.watch(city:city,country:country,category:category,halalOnly:halal,organicOnly:organic,veganOnly:vegan,vegetarianOnly:vegetarian,athleteOnly:athlete),builder:(c,s){if(s.hasError)return const Center(child:Text('تعذر تحميل الخيارات.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد خيارات مطابقة حالياً.'));return ListView.separated(padding:const EdgeInsets.all(12),itemCount:s.data!.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(c,i){final x=s.data![i];return Card(child:ListTile(title:Text(x.name),subtitle:Text(x.category+' • '+x.city+', '+x.country+'\n'+x.priceMinor.toString()+' '+x.currency+((x.halal||x.organic||x.vegan||x.vegetarian||x.athleteFriendly)?' • '+[if(x.halal)'حلال',if(x.organic)'Organic',if(x.vegan)'Vegan',if(x.vegetarian)'Vegetarian',if(x.athleteFriendly)'رياضي'].join(' • '):'')),isThreeLine:true));}}));}}
